lib/Math.sol.content:
pragma solidity ^0.8.0;
uint constant K = 7;
function bump(uint x) pure returns (uint) { return x + 1; }

lib/Errors.sol.content:
pragma solidity ^0.8.0;
uint constant K = 9;
error Bad(uint n);
contract ErrorOwner { error Bad(uint n); }

app/Main.sol.content:
pragma solidity ^0.8.0;
import * as M from "@lib/Math.sol";
import * as E from "@lib/Errors.sol";
import {bump as inc} from "@lib/Math.sol";
import {Bad as Panic} from "@lib/Errors.sol";
using {inc} for uint;
contract SourceUnits {
function ordinary() public pure { assert(M.bump(3) == 4); }
function usingAlias() public pure { assert(uint(3).inc() == 4); }
function constants() public pure { assert(M.K == 7 && E.K == 9); }
function receiverOnce() public pure { uint x = 3; uint y = (x++).inc(); assert(y == 4 && x == 4); }
function qualified() public pure { revert E.Bad(7); }
function nested() public pure { revert E.ErrorOwner.Bad(7); }
function falseControl() public pure { assert(M.bump(3) == 5); }
function moduleEffect() public pure { uint count; ((++count == 1) ? E : E).ErrorOwner; assert(count == 1); }
function failCondition() internal pure returns (bool) { assert(false); return true; }
function moduleConditionFailure() public pure { (failCondition() ? E : E).ErrorOwner; }
function aliasedError() public pure { revert Panic(7); }
function aliasedRequire() public pure { require(false, Panic(7)); }
}
